  function create(key) {
    if (!geometry) throw new Error('Await SolarisAbstracts.ready before creating a figure.');
    if (!Object.prototype.hasOwnProperty.call(geometry, key)) throw new Error('Unknown abstract: ' + key);
    if (!mounted.has(key)) {
      const holder = document.createElement('template');
      holder.innerHTML = geometry[key];
      const svg = holder.content.firstElementChild;
      svg.classList.add('spg-live-art');
      svg.dataset.scene = key;
      svg.setAttribute('focusable', 'false');
      mounted.set(key, svg);
    }
    // Return the same node: move it between card and dialog to avoid duplicate IDs.
    return mounted.get(key);
  }
  function render(svg, key, seconds) {
    if (!Object.prototype.hasOwnProperty.call(updaters, key)) throw new Error('Unknown abstract: ' + key);
    if (!Number.isFinite(seconds) || seconds < 0) throw new Error('Animation time must be finite seconds.');
    updaters[key](svg, seconds);
  }
